    const TitleDef* FindTitle(std::uint16_t a_numericID) noexcept
    {
        const auto it = std::lower_bound(
            kTitles.begin(),
            kTitles.end(),
            a_numericID,
            [](const TitleDef& a_title, std::uint16_t a_id) {
                return a_title.numericID < a_id;
            });

        if (it == kTitles.end() || it->numericID != a_numericID) {
            return nullptr;
        }
        return std::addressof(*it);
    }

    std::span<const Condition> ConditionsOf(const TitleDef& a_title) noexcept
    {
        return std::span<const Condition>{
            kConditions.data() + a_title.conditionOffset,
            a_title.conditionCount
        };
    }

    std::span<const SegmentDef> SegmentsOf(const TitleDef& a_title) noexcept
    {
        return std::span<const SegmentDef>{
            kSegments.data() + a_title.segmentOffset,
            a_title.segmentCount
        };
    }

    const SegmentDef* FindSegment(const TitleDef& a_title, std::uint8_t a_segmentIndex) noexcept
    {
        for (const auto& segment : SegmentsOf(a_title)) {
            if (segment.index == a_segmentIndex) {
                return std::addressof(segment);
            }
        }
        return nullptr;
    }

    bool SegmentSupportsRole(const SegmentDef& a_segment, Role a_role) noexcept
    {
        const auto bit = static_cast<std::uint8_t>(a_role);
        return (a_segment.roleMask & bit) != 0u;
    }

    const SegmentDef* LowestCompatibleSegment(const TitleDef& a_title, Role a_role) noexcept
    {
        const SegmentDef* best = nullptr;
        for (const auto& segment : SegmentsOf(a_title)) {
            if (!SegmentSupportsRole(segment, a_role)) {
                continue;
            }
            if (!best || segment.index < best->index) {
                best = std::addressof(segment);
            }
        }
        return best;
    }

    bool EvaluateTitle(const TitleDef& a_title, const ClassLevels& a_levels) noexcept
    {
        for (const auto& condition : ConditionsOf(a_title)) {
            switch (condition.kind) {
            case ConditionKind::kClassMinLevel:
                if (condition.classID >= a_levels.size() ||
                    a_levels[condition.classID] < condition.minLevel) {
                    return false;
                }
                break;

            case ConditionKind::kClassCountThreshold:
            {
                std::uint8_t count = 0;
                for (std::uint8_t classID = 0; classID < a_levels.size(); ++classID) {
                    const auto bit = static_cast<std::uint16_t>(1u << classID);
                    if ((condition.eligibleClassMask & bit) != 0u &&
                        a_levels[classID] >= condition.minLevelEach) {
                        ++count;
                    }
                }
                if (count < condition.minCount) {
                    return false;
                }
                break;
            }
            }
        }
        return true;
    }
